def can_place(n, m, k):
    # Check if there exists at least k horizontal dominoes
    return k <= n * m // 2 - (m - 1)

for _ in range(int(input())):
    n, m, k = map(int, input().split())
    if can_place(n, m, k):
        print('YES')
    else:
        print('NO')
